const escapeHtml = (value) => String(value || '').replace(/[&<>"']/g, (c) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
}[c]));
return $('Sign Portal Link').all()
  .map(entry => entry.json.body || entry.json)
  .map(item => ({
    json: {
      email_present: Boolean(item.email && item.link),
      to: item.email || '',
      subject: 'Evaluación de seguridad de proveedores - VRM',
      html: '<div style="font-family:Arial,sans-serif;max-width:640px;margin:auto;padding:24px;color:#0f172a">' +
        '<h2>Evaluación de seguridad de proveedores</h2>' +
        '<p>Hola,</p>' +
        '<p>Se solicita completar la evaluación de seguridad de <strong>' + escapeHtml(item.legal_name) + '</strong>.</p>' +
        '<p>Utiliza el siguiente enlace seguro, válido durante 30 días y de un solo uso:</p>' +
        '<p><a href="' + escapeHtml(item.link) + '" style="display:inline-block;padding:12px 18px;background:#0891b2;color:#fff;text-decoration:none;border-radius:6px">Completar evaluación</a></p>' +
        '<p style="font-size:12px;color:#64748b">Si no esperabas esta solicitud, contacta al equipo responsable de gestión de proveedores.</p>' +
        '</div>'
    }
  }));

const manual = $('Manual Trigger');
if (!manual.isExecuted) return [];
const trigger = manual.first().json || {};
const request = trigger.body || trigger;
if (!request.request_id) return [];

const due = $('Find Due Vendors').all().map(item => item.json).filter(item => item.id);
const signNode = $('Sign Portal Link');
const signed = signNode.isExecuted ? signNode.all().map(item => item.json.body || item.json) : [];
const signErrors = signed.filter(item => item.error || Number(item.statusCode || 0) >= 400 || item.body?.error).length;
const validSigned = signed.filter(item => !item.error && !item.body?.error && item.assessment_id && item.link);
const expectedEmails = validSigned.filter(item => item.email).length;
const missingEmails = validSigned.filter(item => !item.email).length;

const emailNode = $('Send Invitation Email');
const emailResults = emailNode.isExecuted ? emailNode.all() : [];
const emailErrors = emailResults.some(item =>
  Boolean(item.json?.error || item.json?.errorMessage || item.json?.error?.message)
);
const upstreamErrors = $input.all().some(item =>
  Boolean(item.json?.error || item.json?.errorMessage || item.json?.body?.error)
);
const inputErrors = signErrors > 0 || emailErrors || upstreamErrors;
const sentEmails = emailResults.filter(item =>
  !item.json?.error && !item.json?.errorMessage && !item.json?.error?.message
).length;
const status = inputErrors ? 'failed' : missingEmails > 0 ? 'partial' : 'success';

let summary;
if (due.length === 0) summary = 'No había proveedores con reevaluación vencida.';
else if (signErrors > 0) summary = 'No se pudieron firmar ' + signErrors + ' enlace(s) de evaluación.';
else if (emailErrors || upstreamErrors) summary = 'Se crearon ' + validSigned.length + ' evaluación(es), pero falló la entrega de correo.';
else summary = 'Evaluaciones creadas: ' + validSigned.length + '; correos enviados: ' + sentEmails + '; contactos sin email: ' + missingEmails + '.';

return [{ json: {
  request_id: request.request_id,
  workflow_code: 'wf-05',
  status,
  summary,
  details: {
    due_vendors: due.length,
    invitations_created: validSigned.length,
    signing_errors: signErrors,
    emails_expected: expectedEmails,
    emails_sent: sentEmails,
    email_errors: emailErrors || upstreamErrors,
    missing_contact_emails: missingEmails
  }
} }];
